      "path": "package.json",
      "content": "{\n  \"name\": \"dsh-context\",\n  \"version\": \"0.85.1\",\n  \"description\": \"A DeepSeek Harness plugin for context insight and management, with context dashboard and context command, for understanding how the context is made of, and how it evolves.\",\n  \"icon\": \"icon.svg\",\n  \"author\": \"bowenliang123\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/bowenliang123/dsh-context.git\"\n  },\n  \"homepage\": \"https://github.com/bowenliang123/dsh-context\",\n  \"bugs\": {\n    \"url\": \"https://github.com/bowenliang123/dsh-context/issues\"\n  },\n  \"type\": \"module\",\n  \"engines\": {\n    \"node\": \"^22.19.0 || >=24.0.0\",\n    \"dsh\": \">=0.2.0-rc.2 || >=0.2.1-rc.2 || >=0.2.2-rc.1\"\n  },\n  \"main\": \"lib/index.js\",\n  \"types\": \"lib/index.d.ts\",\n  \"exports\": {\n    \".\": {\n      \"types\": \"./lib/index.d.ts\",\n      \"default\": \"./lib/index.js\"\n    },\n    \"./client\": \"./lib/client.js\",\n    \"./package.json\": \"./package.json\",\n    \"./locale/*.json\": \"./locale/*.json\"\n  },\n  \"files\": [\n    \"icon.svg\",\n    \"locale/*.json\",\n    \"README*.md\",\n    \"lib/client.js\",\n    \"lib/index.js\",\n    \"lib/index.d.ts\",\n    \"cordis.patch.yml\",\n    \"LICENSE\"\n  ],\n  \"scripts\": {\n    \"build\": \"tsdown\",\n    \"lint\": \"oxlint\",\n    \"lint:fix\": \"oxlint --fix\",\n    \"check\": \"node scripts/run-bash.mjs scripts/check.sh\",\n    \"watch\": \"node scripts/watch.mjs\",\n    \"web\": \"node scripts/web.mjs\",\n    \"register\": \"node scripts/run-bash.mjs scripts/register.sh\",\n    \"typecheck\": \"tsc --noEmit -p tsconfig.tests.json --incremental\",\n    \"test\": \"vitest run --coverage\",\n    \"coverage\": \"vitest run --coverage\",\n    \"release\": \"node scripts/run-bash.mjs scripts/publish.sh\",\n    \"social-preview\": \"node scripts/social-preview/generate.ts\",\n    \"prepare\": \"husky && tsdown\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"inject\": [\n        \"@deepseek-ai/dsh-api-remotes\",\n        \"@deepseek-ai/dsh-client-connection\",\n        \"@deepseek-ai/dsh-client-locale\",\n        \"@deepseek-ai/dsh-client-ui-conversation\",\n        \"@deepseek-ai/dsh-client-ui-settings\",\n        \"@deepseek-ai/dsh-client-ui-sidebar-right\"\n      ],\n      \"platform\": \"web\"\n    },\n    \"compatibility\": {\n      \"dshReleases\": {\n        \"0.2.0-rc.2+\": \"compatible\",\n        \"0.2.1-rc.2+\": \"compatible\",\n        \"0.2.2-rc.1+\": \"compatible\",\n        \"0.2.2-rc.3+\": \"compatible\"\n      }\n    }\n  },\n  \"keywords\": [\n    \"deepseek-harness\",\n    \"dsh\",\n    \"cordis\",\n    \"plugin\",\n    \"context\",\n    \"token\",\n    \"ui\"\n  ],\n  \"license\": \"Apache-2.0\",\n  \"dependencies\": {\n    \"zod\": \"^4.6.6\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.4 || >=4.0.6-alpha.2 <5.0.0\",\n    \"@deepseek-ai/dsh-client-ui-primitives\": \">=0.2.0-rc.2 || >=0.2.1-rc.2 || >=0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-session\": \">=0.2.0-rc.2 || >=0.2.1-rc.2 || >=0.2.2-rc.1\",\n    \"@deepseek-ai/schemastery\": \"^3.18.2 || >=3.18.6-alpha.2 <4.0.0\",\n    \"react\": \"^18.3.1\",\n    \"react-dom\": \"^18.3.1\"\n  },\n  \"peerDependenciesMeta\": {\n    \"@deepseek-ai/dsh-client-ui-primitives\": {\n      \"optional\": true\n    },\n    \"react\": {\n      \"optional\": true\n    },\n    \"react-dom\": {\n      \"optional\": true\n    }\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"4.1.0\",\n    \"@deepseek-ai/dsh-client-store\": \"0.2.0-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-primitives\": \"0.2.0-rc.2\",\n    \"@deepseek-ai/dsh-session\": \"0.2.0-rc.2\",\n    \"@deepseek-ai/dsh-session-projection\": \"0.2.0-rc.2\",\n    \"@deepseek-ai/dsh-util-code-language\": \"0.2.0-rc.2\",\n    \"@deepseek-ai/dsh-util-workspace-path\": \"0.2.0-rc.2\",\n    \"@deepseek-ai/schemastery\": \"3.19.0\",\n    \"@shikijs/langs\": \"^4.5.0\",\n    \"@stylistic/eslint-plugin\": \"^5.10.0\",\n    \"@tailwindcss/node\": \"4.3.3\",\n    \"@tailwindcss/oxide\": \"4.3.3\",\n    \"@types/jsdom\": \"^30.0.0\",\n    \"@types/node\": \"^26.6.5\",\n    \"@types/react\": \"^18.3.31\",\n    \"@types/react-dom\": \"^18.3.7\",\n    \"@types/semver\": \"^7.8.0\",\n    \"@vitest/coverage-v8\": \"^5.1.0\",\n    \"anser\": \"^2.3.5\",\n    \"clsx\": \"^2.1.1\",\n    \"diff\": \"^9.0.0\",\n    \"eslint-plugin-sonarjs\": \"^4.2.2\",\n    \"husky\": \"^9.1.7\",\n    \"immer\": \"^10.2.0\",\n    \"jsdom\": \"^30.1.3\",\n    \"katex\": \"^0.16.47\",\n    \"lightningcss\": \"1.32.0\",\n    \"mdast-util-from-markdown\": \"^2.1.0\",\n    \"mdast-util-gfm\": \"^3.1.0\",\n    \"mdast-util-math\": \"^3.0.0\",\n    \"micromark-core-commonmark\": \"^2.0.4\",\n    \"micromark-extension-gfm\": \"^3.0.0\",\n    \"micromark-extension-math\": \"^3.1.0\",\n    \"micromark-factory-space\": \"^2.1.0\",\n    \"micromark-util-character\": \"^2.1.1\",\n    \"micromark-util-classify-character\": \"^2.0.1\",\n    \"micromark-util-sanitize-uri\": \"^2.0.1\",\n    \"micromark-util-symbol\": \"^2.0.1\",\n    \"oxlint\": \"1.85.0\",\n    \"oxlint-tsgolint\": \"7.0.2003\",\n    \"playwright-core\": \"^1.65.0\",\n    \"react\": \"^18.3.1\",\n    \"react-dom\": \"^18.3.1\",\n    \"semver\": \"^7.8.5\",\n    \"shiki\": \"^4.5.0\",\n    \"simple-icons\": \"16.32.0\",\n    \"tsdown\": \"0.23.7\",\n    \"typescript\": \"~7.0.2\",\n    \"vitest\": \"^5.1.0\",\n    \"zustand\": \"~4.4.7\"\n  }\n}\n"
