    {
      "path": "cordis.patch.yml",
      "content": "# Bundle patch layer: the row loads the package's main entry as the host half\n# (a plain Cordis plugin); the `dsh.client` declaration makes the web app load\n# its ./client bundle as the browser half.\n- insert:\n    - id: dsh-context\n      name: dsh-context\n"
    },
    {
      "path": "src/client/components/browserHelpers.ts",
      "content": "import type { Assembled } from '../../shared/assemble'\nimport type { Category, RequestRecord, SurfaceNode } from '../../shared/types'\nimport type { DefaultDeltaBase } from '../settings'\nimport type { RowKind } from './browserNodes'\n\nexport interface CatFocus {\n  cat: string\n  kind?: RowKind\n  step?: number\n  query?: string\n}\n\nexport function countOf(asm: Assembled, byCat: Partial<Record<Category, SurfaceNode[]>>, c: string): number {\n  if (c === 'system') return asm.system !== null ? 1 : 0\n  if (c === 'tools') return asm.header !== null ? asm.header.tools.length : 0\n  return byCat[c as Category]?.length ?? 0\n}\n\nexport function lastOfTurn(requests: readonly RequestRecord[], turn: number): RequestRecord | null {\n  for (let i = requests.length - 1; i >= 0; i--) if ((requests[i].turn ?? 0) === turn) return requests[i]\n  return null\n}\n\nexport function baseRequestOf(\n  requests: readonly RequestRecord[],\n  req: RequestRecord | null,\n  base: DefaultDeltaBase,\n): RequestRecord | null {\n  if (req === null) {\n    const last = requests.length > 0 ? requests[requests.length - 1] : null\n    if (last === null) return null\n    return base === 'step' ? last : lastOfTurn(requests, (last.turn ?? 0) - 1)\n  }\n  if (base === 'turn') return lastOfTurn(requests, (req.turn ?? 0) - 1)\n  const i = requests.indexOf(req)\n  return i > 0 ? requests[i - 1] : null\n}\n\nexport function findRowByKey(root: HTMLElement, key: string): HTMLElement | null {\n  for (const row of root.querySelectorAll<HTMLElement>('[data-lc-key]')) {\n    if (row.dataset.lcKey === key) return row\n  }\n  return null\n}\n\nexport const safeIdPart = (key: string): string => key.replace(/[^a-zA-Z0-9_-]/g, '_')\n\nexport const STEP_PICK_MAX = 500\n\nexport interface StepPickOption {\n  value: string\n  label: string\n}\n\nfunction stepMatches(option: StepPickOption, query: string): boolean {\n  return `${option.label} ${option.value}`.toLowerCase().includes(query)\n}\n\nexport function stepPickOptionsOf(\n  requests: readonly RequestRecord[],\n  sel: 'live' | number,\n  seq: number | null,\n  live: StepPickOption,\n  optionOf: (request: RequestRecord) => StepPickOption,\n): StepPickOption[] {\n  const count = requests.length\n  let from = Math.max(0, count - STEP_PICK_MAX)\n  if (count > STEP_PICK_MAX) {\n    const newest = requests[from]\n    const selSeq = typeof sel === 'number' && (seq === null || seq < newest.seq) ? sel : null\n    if (selSeq !== null) {\n      let low = 0\n      let high = count - 1\n      let idx = count - 1\n      while (low <= high) {\n        const mid = (low + high) >> 1\n        if (requests[mid].seq >= selSeq) { idx = mid; high = mid - 1 } else low = mid + 1\n      }\n      from = Math.max(0, idx - (STEP_PICK_MAX >> 1))\n    }\n  }\n  return [live, ...requests.slice(from, from + STEP_PICK_MAX).map(optionOf).reverse()]\n}\n\nexport function stepPickMatchesOf(\n  requests: readonly RequestRecord[],\n  query: string,\n  live: StepPickOption,\n  optionOf: (request: RequestRecord) => StepPickOption,\n): StepPickOption[] {\n  const q = query.trim().toLowerCase()\n  const out: StepPickOption[] = stepMatches(live, q) ? [live] : []\n  for (let i = requests.length - 1; i >= 0 && out.length < STEP_PICK_MAX; i--) {\n    const option = optionOf(requests[i])\n    if (stepMatches(option, q)) out.push(option)\n  }\n  return out\n}\n\nexport const nodeEstimateSize = (): number => 30\n\nexport function stepStampOf(requests: RequestRecord[]): (itemSeq: number) => { turn: number; step: number } | null {\n  const sorted = requests.slice().sort((a, b) => a.seq - b.seq)\n  return (itemSeq) => {\n    for (const r of sorted) {\n      if (r.seq > itemSeq) {\n        return typeof r.turn === 'number' && typeof r.step === 'number' ? { turn: r.turn, step: r.step } : null\n      }\n    }\n    return null\n  }\n}\n\nexport const DNA_MIN_BAND = 0.35\n"
    },
    {
      "path": "src/client/index.ts",
      "content": "import { createElement as h } from 'react'\nimport { DICTS } from './i18n'\nimport { registerContextCommand } from './command'\nimport { makeContextModal } from './components/contextModal'\nimport { makeOverviewPanel } from './components/overviewPanel'\nimport { resetSessionWarm } from './prefetch'\nimport { disposeRetention } from './retention'\nimport { resetTimelineDetailStores } from './timelineSource'\nimport { clearAttachmentPaths } from './attachmentSource'\nimport { makePluginConfigCard } from './components/settingsCard'\nimport { watchInsightPage } from './insightPage'\nimport { modalStoreOf } from './modalStore'\nimport { CONTEXT_VIEW_ID, asRecord, entrySeated, type ClientCtx } from './services'\nimport { createContextSettings, type ConfigFormsFace, type SettingsField } from './settings'\nimport { makeContextView } from './components/contextView'\nimport { makeContextJumpButton } from './components/contextJump'\nimport { makeFleetView } from './components/fleetView'\nimport { watchFleetTab } from './fleetTab'\nimport { makeAgentHeads } from './agentHeads'\nimport { watchHistoryFaces } from './historyPage'\nimport { resetVersionSource } from './versionSource'\nimport { registerCostRefresh, resetCostRefresh } from './costRefresh'\nimport { watchPlacement } from './placement'\nimport { watchSidebarContextTab } from './sidebar'\nimport { makeViewKit } from './viewkit'\n\nimport './styles/tailwind.css'\nimport './styles/base.css'\nimport './styles/stats.css'\nimport './styles/jump.css'\nimport './styles/settings.css'\nimport './styles/stackedBar.css'\nimport './styles/trendChart.css'\nimport './styles/requestDetail.css'\nimport './styles/events.css'\nimport './styles/fileCard.css'\nimport './styles/commandPanel.css'\nimport './styles/modal.css'\nimport './styles/browser.css'\nimport './styles/detailSections.css'\nimport './styles/attachments.css'\nimport './styles/agentGraph.css'\nimport './styles/fleet.css'\nimport './styles/pulse.css'\nimport './styles/overview.css'\nimport './styles/dateRange.css'\nimport './styles/recom.css'\n\nconst NS = 'dsh-context'\n\nfunction refreshCostDependents(ctx: ClientCtx): void {\n  try {\n    const sessions = ctx.get('sessions') as {\n      refresh?(): unknown\n      getSnapshot?(): unknown\n      refreshProjections?(id: string): unknown\n    } | undefined\n    if (sessions === undefined) return\n    void Promise.resolve(sessions.refresh?.()).catch(() => {})\n    const state = asRecord(sessions.getSnapshot?.())\n    const current = typeof state?.current === 'string' ? state.current : undefined\n    if (current !== undefined) void Promise.resolve(sessions.refreshProjections?.(current)).catch(() => {})\n  } catch {\n  }\n}\n\nconst JUMP_SLOT = 'conversation.chat.assistant-actions'\nconst JUMP_ID = 'context-jump'\n\nfunction apply(ctx: ClientCtx): void {\n  if (entrySeated(ctx, JUMP_SLOT, JUMP_ID)) return\n  ctx.effect(() => {\n    return ctx.locale.register(NS, DICTS)\n  }, 'dsh-context: dictionaries')\n  const t = ctx.locale.bind(NS)\n\n  const kit = makeViewKit(t, ctx.locale)\n  ctx.effect(() => () => {\n    resetSessionWarm()\n    resetTimelineDetailStores()\n    clearAttachmentPaths()\n    resetVersionSource()\n    resetCostRefresh()\n    disposeRetention()\n  }, 'dsh-context: warm-up timers')\n  ctx.effect(() => registerCostRefresh(() => { refreshCostDependents(ctx) }), 'dsh-context: cost refresh')\n  watchHistoryFaces(ctx)\n  const settings = createContextSettings()\n  const heads = makeAgentHeads()\n  const ContextView = makeContextView(ctx, kit, settings, heads)\n  const FleetView = makeFleetView(ctx, kit, heads)\n\n  ctx.effect(() => watchPlacement(settings, {\n    tab: () => ctx.slots.inject('conversation.view', () => ctx.slots.register(\n      { name: 'conversation.view', id: CONTEXT_VIEW_ID, order: 20, locale: NS, label: () => t('tab.context') },\n      props => h(ContextView, props),\n    )),\n    sidebar: () => watchSidebarContextTab(ctx, ContextView, t, NS),\n  }), 'dsh-context: placement')\n\n  ctx.effect(() => watchFleetTab(\n    ctx,\n    settings,\n    props => h(FleetView, props as unknown as Parameters<typeof FleetView>[0]),\n    t,\n    NS,\n  ), 'dsh-context: fleet tab')\n\n  const ContextJump = makeContextJumpButton(ctx, kit, settings)\n  ctx.slots.inject(JUMP_SLOT, () => {\n    return ctx.slots.register(\n      { name: JUMP_SLOT, id: JUMP_ID, order: 20, locale: NS },\n      props => h(ContextJump, props),\n    )\n  })\n\n  registerContextCommand(ctx, kit)\n  const ContextModal = makeContextModal(ctx, kit, settings)\n  ctx.slots.inject('conversation.input.overlay', () => {\n    return ctx.slots.register(\n      { name: 'conversation.input.overlay',\n        id: 'context-modal',\n        order: 10,\n        locale: NS,\n        inject: (sessionId = '') => ({ hooks: { contextModal: modalStoreOf(sessionId) }, warm: true }) },\n      props => h(ContextModal, props),\n    )\n  })\n\n  const OverviewPanel = makeOverviewPanel(ctx, kit, settings)\n  ctx.effect(() => watchInsightPage(\n    ctx,\n    settings,\n    props => h(OverviewPanel, props as unknown as Parameters<typeof OverviewPanel>[0]),\n    t,\n    NS,\n  ), 'dsh-context: insight page')\n\n  const cardFace = (): {\n    hooks: { contextSettings: typeof settings.store }\n    set: (field: SettingsField, value: string) => void\n  } => ({\n    hooks: { contextSettings: settings.store },\n    set: (field, value) => { settings.set(field, value) },\n  })\n\n  ctx.inject(['configForms'], (raw) => {\n    const c = raw as ClientCtx & { configForms?: ConfigFormsFace }\n    const forms = c.configForms\n    if (forms === undefined || typeof forms.get !== 'function' || typeof forms.whileServed !== 'function') return\n    c.effect(() => settings.attach(forms.get(NS)), 'dsh-context: config forms')\n    const PluginConfigCard = makePluginConfigCard(kit)\n    c.effect(() => forms.whileServed([NS], () => {\n      return c.slots.inject('plugins.bundle.config', () => {\n        return c.slots.register(\n          { name: 'plugins.bundle.config', key: NS, locale: NS, inject: cardFace },\n          props => h(PluginConfigCard, props as unknown as Parameters<typeof PluginConfigCard>[0]),\n        )\n      }) as () => void\n    }), 'dsh-context: plugins-page card')\n  })\n}\n\nmodule.exports = {\n  name: 'dsh-context',\n  inject: ['slots', 'locale'],\n  apply,\n}\n"
    },
    {
      "path": "src/client/sessionData.ts",
      "content": "import type { ContextBreakdown, ContextPressure, ContextTimeline, TokenUsage } from '../shared/types'\nimport { contextBreakdownOf, contextPressureOf, projectionOf, tokenUsageOf, type SessionStandardProps } from './services'\nimport { useTimelineSource, type TimelineSource } from './timelineSource'\n\ninterface ContextSession {\n  source: TimelineSource\n  data: ContextTimeline | null\n  pressure: ContextPressure | null\n  breakdown: ContextBreakdown | null\n  usage: TokenUsage | null\n}\n\nexport function useContextSession(props: SessionStandardProps): ContextSession {\n  const source = useTimelineSource(props)\n  return {\n    source,\n    data: source.data,\n    pressure: projectionOf(props, 'contextPressure', contextPressureOf),\n    breakdown: projectionOf(props, 'contextBreakdown', contextBreakdownOf),\n    usage: projectionOf(props, 'tokenUsage', tokenUsageOf),\n  }\n}\n"
    },
    {
      "path": "src/client/timelineSource.ts",
      "content": "import { useEffect, useMemo, useSyncExternalStore } from 'react'\nimport type { ContextTimeline, ContextTimelineDetail, HeaderRecord, HeaderTool, RequestRecord, SurfaceNode, SurfaceNodeWindow, SystemPromptNode } from '../shared/types'\nimport { CATS } from '../shared/categories'\nimport type { ContextDelta } from '../shared/delta'\nimport type { IncrementCat } from '../shared/increment'\nimport { DELTA_ROUTE, DETAIL_ROUTE, FACTS_ROUTE } from './apiRoutes'\nimport { subscribeInvalidations } from './invalidation'\nimport { noteCostPending } from './costRefresh'\nimport { makeRetentionCache } from './retention'\nimport { postRoute, postRouteQuietly, RouteError } from './route'\nimport type { SessionStandardProps } from './services'\nimport { asRecord, collectionsOf, projectionOf, timelineOf } from './services'\n\nexport type FactPart = 'requests' | 'nodes' | 'events' | 'files' | 'commands' | 'spans'\n\nexport interface FactWindow {\n  requestsTail?: number\n  nodesTail?: number\n  eventsTail?: number\n  filesTail?: number\n  commandsTail?: number\n  spansTail?: number\n}\n\ninterface FactParts {\n  head?: ContextTimeline\n  series?: RequestRecord[]\n  requests?: RequestRecord[]\n  nodes?: SurfaceNodeWindow\n  events?: ContextTimeline['events']\n  files?: { fileOps: NonNullable<ContextTimeline['fileOps']>; fileOpsFloor?: number }\n  commands?: { commands: NonNullable<ContextTimeline['commands']>; commandsFloor?: number; commandStats?: ContextTimeline['commandStats'] }\n  spans?: NonNullable<ContextTimeline['spans']>\n}\n\nexport interface FactsRead {\n  rev: number\n  live: boolean\n  asOfSeq?: number\n  parts: FactParts\n  missing?: readonly string[]\n}\n\nfunction numOf(value: unknown): number | undefined {\n  return typeof value === 'number' && Number.isFinite(value) && value >= 0 ? value : undefined\n}\n\nfunction rowsOf(value: unknown): Record<string, unknown>[] | undefined {\n  if (!Array.isArray(value)) return undefined\n  return value.filter((entry): entry is Record<string, unknown> => entry !== null && typeof entry === 'object')\n}\n\nfunction nodesPartOf(value: unknown): SurfaceNodeWindow | undefined {\n  const data = asRecord(value)\n  if (data === null) return undefined\n  const nodes = rowsOf(data.nodes) as SurfaceNode[] | undefined\n  const archive = rowsOf(data.archive) as SurfaceNode[] | undefined\n  if (nodes === undefined || archive === undefined) return undefined\n  return {\n    nodes,\n    archive,\n    droppedNodes: numOf(data.droppedNodes) ?? 0,\n    ...(numOf(data.surfaceFloor) === undefined ? {} : { surfaceFloor: numOf(data.surfaceFloor) }),\n    ...(numOf(data.archiveFloor) === undefined ? {} : { archiveFloor: numOf(data.archiveFloor) }),\n  }\n}\n\nexport function factsOf(value: unknown): FactsRead | null {\n  const data = asRecord(value)\n  if (data === null) return null\n  const rev = numOf(data.rev)\n  if (rev === undefined) return null\n  const parts = asRecord(data.parts)\n  if (parts === null) return null\n  const head = parts.head === undefined ? undefined : timelineOf(parts.head)\n  const series = rowsOf(parts.series) as RequestRecord[] | undefined\n  const requests = rowsOf(parts.requests) as RequestRecord[] | undefined\n  const events = rowsOf(parts.events) as ContextTimeline['events'] | undefined\n  const spans = rowsOf(parts.spans) as NonNullable<ContextTimeline['spans']> | undefined\n  const files = asRecord(parts.files)\n  const fileOps = files === null ? undefined : rowsOf(files.fileOps) as NonNullable<ContextTimeline['fileOps']> | undefined\n  const commands = asRecord(parts.commands)\n  const commandRows = commands === null ? undefined : rowsOf(commands.commands) as NonNullable<ContextTimeline['commands']> | undefined\n  const stats = asRecord(commands?.commandStats)\n  const nodes = nodesPartOf(parts.nodes)\n  const fileOpsFloor = files === null ? undefined : numOf(files.fileOpsFloor)\n  const commandsFloor = commands === null ? undefined : numOf(commands.commandsFloor)\n  const missing = Array.isArray(data.missing) ? data.missing.filter((entry): entry is string => typeof entry === 'string') : undefined\n  return {\n    rev,\n    live: data.live === true,\n    ...(numOf(data.asOfSeq) === undefined ? {} : { asOfSeq: numOf(data.asOfSeq) }),\n    parts: {\n      ...(head === null || head === undefined ? {} : { head }),\n      ...(series === undefined ? {} : { series }),\n      ...(requests === undefined ? {} : { requests }),\n      ...(nodes === undefined ? {} : { nodes }),\n      ...(events === undefined ? {} : { events }),\n      ...(fileOps === undefined\n        ? {}\n        : {\n          files: {\n            fileOps,\n            ...(fileOpsFloor === undefined ? {} : { fileOpsFloor }),\n          },\n        }),\n      ...(commandRows === undefined\n        ? {}\n        : {\n          commands: {\n            commands: commandRows,\n            ...(commandsFloor === undefined ? {} : { commandsFloor }),\n            ...(stats === null\n              ? {}\n              : {\n                commandStats: {\n                  runs: numOf(stats.runs) ?? 0,\n                  failed: numOf(stats.failed) ?? 0,\n                  ms: numOf(stats.ms) ?? 0,\n                  bg: numOf(stats.bg) ?? 0,\n                },\n              }),\n          },\n        }),\n      ...(spans === undefined ? {} : { spans }),\n    },\n    ...(missing === undefined || missing.length === 0 ? {} : { missing }),\n  }\n}\n\nexport function detailOf(value: unknown): ContextTimelineDetail | null {\n  const data = asRecord(value)\n  if (data === null) return null\n  if (typeof data.rev !== 'number' || !Number.isFinite(data.rev) || data.rev < 0) return null\n  const head = timelineOf(data.head)\n  return {\n    rev: data.rev,\n    ...(head !== null ? { head } : {}),\n    ...collectionsOf(data),\n  }\n}\n\nexport function makeDetailFetcher(\n  sessionId: string,\n): (() => Promise<ContextTimelineDetail | null>) | undefined {\n  if (sessionId === '') return undefined\n  return () => postRoute(DETAIL_ROUTE, { sessionId }, detailOf, { label: 'detail' })\n}\n\nexport type DeltaFetcher = (seq: number | null, baseSeq: number | null) => Promise<ContextDelta | null>\n\nfunction countRecordOf(value: unknown): Record<IncrementCat, number> | null {\n  const record = asRecord(value)\n  if (record === null) return null\n  const out = {} as Record<IncrementCat, number>\n  for (const cat of CATS) {\n    const n = numOf(record[cat.key])\n    if (n === undefined) return null\n    out[cat.key] = n\n  }\n  return out\n}\n\nfunction nullableOf(value: unknown): Record<string, unknown> | null | undefined {\n  if (value === null) return null\n  return asRecord(value) ?? undefined\n}\n\nexport function deltaOf(value: unknown): ContextDelta | null {\n  const data = asRecord(value)\n  if (data === null) return null\n  const added = rowsOf(data.added) as SurfaceNode[] | undefined\n  const viewNodes = rowsOf(data.viewNodes) as SurfaceNode[] | undefined\n  const viewHeader = nullableOf(data.viewHeader)\n  const viewSystem = nullableOf(data.viewSystem)\n  const system = nullableOf(data.system)\n  const tools = rowsOf(data.tools) as HeaderTool[] | undefined\n  const header = nullableOf(data.header)\n  const counts = countRecordOf(data.counts)\n  const tokens = countRecordOf(data.tokens)\n  const removedCounts = countRecordOf(data.removedCounts)\n  const tokenUp = countRecordOf(data.tokenUp)\n  const tokenDown = countRecordOf(data.tokenDown)\n  const items = numOf(data.items)\n  const total = numOf(data.total)\n  if (added === undefined || viewNodes === undefined\n    || viewHeader === undefined || viewSystem === undefined || system === undefined\n    || tools === undefined || header === undefined\n    || counts === null || tokens === null || removedCounts === null\n    || tokenUp === null || tokenDown === null\n    || items === undefined || total === undefined) return null\n  return {\n    added,\n    viewNodes,\n    viewHeader: viewHeader as HeaderRecord | null,\n    viewSystem: viewSystem as SystemPromptNode | null,\n    system: system as SystemPromptNode | null,\n    tools,\n    header: header as HeaderRecord | null,\n    counts,\n    tokens,\n    removedCounts,\n    tokenUp,\n    tokenDown,\n    items,\n    total,\n  }\n}\n\nexport function makeDeltaFetcher(sessionId: string): DeltaFetcher | undefined {\n  if (sessionId === '') return undefined\n  return (seq, baseSeq) => postRouteQuietly(\n    DELTA_ROUTE,\n    { sessionId, seq, baseSeq },\n    deltaOf,\n    { label: 'delta' },\n  )\n}\n\ntype CoreRead = FactsRead | ContextTimelineDetail\n\nexport interface FactsFetchers {\n  core: () => Promise<CoreRead | null>\n  part: (part: FactPart, window: FactWindow) => Promise<CoreRead | null>\n  legacy?: CoreFetcher\n}\n\nexport function makeFactsFetchers(sessionId: string): FactsFetchers | undefined {\n  if (sessionId === '') return undefined\n  const read = (parts: readonly (FactPart | 'head' | 'series')[], window?: FactWindow): Promise<CoreRead | null> => postRoute(\n    FACTS_ROUTE,\n    { sessionId, parts, ...(window === undefined ? {} : { window }) },\n    value => factsOf(value) ?? detailOf(value),\n    { label: 'facts' },\n  )\n  return {\n    core: () => read(['head', 'series']),\n    part: (part, window) => read([part], window),\n    legacy: makeDetailFetcher(sessionId) as CoreFetcher,\n  }\n}\n\ntype CoreFetcher = () => Promise<ContextTimelineDetail | null>\n\ntype StoreFetcher = CoreFetcher | FactsFetchers\n\ninterface DetailSnap {\n  detail: ContextTimelineDetail | null\n  failed: boolean\n  pending: boolean\n}\n\nconst EMPTY_SNAP: DetailSnap = { detail: null, failed: false, pending: false }\n\nconst DETAIL_DEBOUNCE_MS = 300\n\nconst EAGER_DELAY_MS = 16\n\nconst CATCH_UP_MS = 1_000\n\nconst PART_RETRY_MS = 1_000\n\nconst PART_RETRY_LIMIT = 3\n\nfunction emptyDetail(rev: number, head?: ContextTimeline, requests?: RequestRecord[]): ContextTimelineDetail {\n  return {\n    rev,\n    ...(head === undefined ? {} : { head }),\n    requests: requests ?? [],\n    events: [],\n    nodes: [],\n    droppedNodes: 0,\n    archive: [],\n  }\n}\n\nfunction seriesHasBreakdown(series: readonly RequestRecord[]): boolean {\n  return series.every(request => typeof request.system === 'number' || typeof request.assistant === 'number' || typeof request.tool === 'number')\n}\n\nfunction sameWindow(a: FactWindow, b: FactWindow): boolean {\n  return a.requestsTail === b.requestsTail && a.nodesTail === b.nodesTail && a.eventsTail === b.eventsTail\n    && a.filesTail === b.filesTail && a.commandsTail === b.commandsTail && a.spansTail === b.spansTail\n}\n\nfunction carriedDetail(prev: ContextTimelineDetail, facts: FactsRead): ContextTimelineDetail {\n  return {\n    ...prev,\n    rev: facts.rev,\n    head: facts.parts.head ?? prev.head,\n    requests: facts.parts.series ?? prev.requests,\n  }\n}\n\nfunction detailFromFacts(facts: FactsRead, prev: ContextTimelineDetail | null): ContextTimelineDetail {\n  const base = prev === null\n    ? emptyDetail(facts.rev, facts.parts.head, facts.parts.series ?? facts.parts.requests)\n    : carriedDetail(prev, facts)\n  return mergeFactsInto(base, facts)\n}\n\nfunction withoutPart(detail: ContextTimelineDetail, part: FactPart): ContextTimelineDetail {\n  if (part === 'requests') return detail\n  const next: ContextTimelineDetail = { ...detail }\n  switch (part) {\n    case 'events':\n      next.events = []\n      break\n    case 'nodes':\n      next.nodes = []\n      next.droppedNodes = 0\n      next.archive = []\n      delete next.surfaceFloor\n      delete next.archiveFloor\n      break\n    case 'files':\n      delete next.fileOps\n      delete next.fileOpsFloor\n      break\n    case 'commands':\n      delete next.commands\n      delete next.commandsFloor\n      delete next.commandStats\n      break\n    case 'spans':\n      delete next.spans\n      break\n  }\n  return next\n}\n\nfunction mergeFactsInto(detail: ContextTimelineDetail, facts: Fa